module debate_solver #(\n    parameter N = 4,  // Max number of candidates (1-4)\n    parameter K = 8   // Max number of utterances (1-8)\n)(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    \n    // Utterance data - packed arrays\n    // Each utterance: speaker_id (4b), op_code (4b), arg1 (4b), arg2 (4b)\n    // op_code: 0=truther, 1=fabulist, 2=charlatan, 3=not, 4=and, 5=xor\n    input wire [3:0] u_speaker [0:K-1],\n    input wire [3:0] u_op     [0:K-1],\n    input wire [3:0] u_arg1   [0:K-1],\n    input wire [3:0] u_arg2   [0:K-1],\n    \n    // Actual counts (0 to K-1, 0 to N-1)\n    input wire [7:0] num_utterances,\n    input wire [3:0] num_candidates,\n    \n    // Outputs: type per candidate (0=truther, 1=fabulist, 2=charlatan)\n    output reg [1:0] result_type [0:N-1],\n    output reg valid,\n    output reg done\n);\n\n// State machine states\nlocalparam [2:0] S_IDLE = 3'd0;\nlocalparam [2:0] S_CHECK_ASSIGN = 3'd1;\nlocalparam [2:0] S_EVAL_STMT = 3'd2;\nlocalparam [2:0] S_CHECK_CHARLATAN = 3'd3;\nlocalparam [2:0] S_NEXT_ASSIGN = 3'd4;\nlocalparam [2:0] S_DONE = 3'd5;\n\nreg [2:0] state;\nreg [7:0] assign_idx;  // 0 to 3^N-1\nreg [7:0] stmt_idx;    // 0 to K-1\nreg [2:0] cand_idx;    // 0 to N-1\nreg [7:0] utter_idx;   // 0 to K-1 for charlatan check\n\n// Current assignment being tested (N*2 bits)\nreg [1:0] current_assign [0:N-1];\n\n// Storage for evaluation results\nreg eval_result;\nreg [7:0] switch_point;  // For charlatan validation\n\n// Helper: Get assignment for candidate (encoded in assign_idx)\nfunction [1:0] get_assign;\n    input [7:0] base;\n    input [2:0] cand;\n    integer i;\n    begin\n        // Decode ternary representation of assign_idx\n        get_assign = 2'b00;\n        // Simplified: use assign_idx modulo 3^N, extract candidate bits\n        // This is a placeholder - actual implementation needs proper ternary decoding\n    end\nendfunction\n\n// Helper: Evaluate a statement for current assignment\nfunction eval_statement;\n    input [3:0] op;\n    input [3:0] a1;\n    input [3:0] a2;\n    reg [1:0] type1, type2;\n    begin\n        case(op)\n            0: begin // truther n\n                eval_statement = (current_assign[a1-1] == 0);\n            end\n            1: begin // fabulist n\n                eval_statement = (current_assign[a1-1] == 1);\n            end\n            2: begin // charlatan n\n                eval_statement = (current_assign[a1-1] == 2);\n            end\n            3: begin // not p\n                // p is arg1 (simplified: only leaf supported)\n                eval_statement = !eval_statement(u_op[a1], u_arg1[a1], u_arg2[a1]);\n            end\n            4: begin // and p q\n                eval_statement = eval_statement(u_op[a1], u_arg1[a1], u_arg2[a1]) && \n                                eval_statement(u_op[a2], u_arg1[a2], u_arg2[a2]);\n            end\n            5: begin // xor p q\n                eval_statement = eval_statement(u_op[a1], u_arg1[a1], u_arg2[a1]) ^ \n                                eval_statement(u_op[a2], u_arg1[a2], u_arg2[a2]);\n            end\n            default: eval_statement = 0;\n        endcase\n    end\nendfunction\n\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= S_IDLE;\n        valid <= 1'b0;\n        done <= 1'b0;\n        assign_idx <= 8'd0;\n        stmt_idx <= 8'd0;\n        cand_idx <= 3'd0;\n        utter_idx <= 8'd0;\n    end else begin\n        case (state)\n            S_IDLE: begin\n                if (start) begin\n                    state <= S_CHECK_ASSIGN;\n                    assign_idx <= 8'd0;\n                    valid <= 1'b0;\n                    done <= 1'b0;\n                end\n            end\n            \n            S_CHECK_ASSIGN: begin\n                // Decode assign_idx to current_assign (simplified)\n                // For benchmark purposes, this is a placeholder\n                if (assign_idx >= 81) begin // 3^4 = 81\n                    state <= S_DONE;\n                end else begin\n                    state <= S_EVAL_STMT;\n                    stmt_idx <= 8'd0;\n                end\n            end\n            \n            S_EVAL_STMT: begin\n                if (stmt_idx >= num_utterances) begin\n                    // All statements evaluated, check charlatan constraints\n                    state <= S_CHECK_CHARLATAN;\n                    cand_idx <= 3'd0;\n                end else begin\n                    // Evaluate this statement\n                    // Check if speaker's type matches statement truth value\n                    // This is simplified - actual would check all utterances\n                    stmt_idx <= stmt_idx + 8'd1;\n                end\n            end\n            \n            S_CHECK_CHARLATAN: begin\n                // Verify charlatan ordering constraints\n                // If all candidates pass, this assignment is valid\n                if (cand_idx >= num_candidates) begin\n                    valid <= 1'b1;\n                    // Store result\n                    for (integer i = 0; i < N; i = i + 1) begin\n                        result_type[i] <= current_assign[i];\n                    end\n                    state <= S_DONE;\n                end else begin\n                    // Check this candidate's utterances for charlatan condition\n                    state <= S_NEXT_ASSIGN;\n                    cand_idx <= cand_idx + 3'd1;\n                end\n            end\n            \n            S_NEXT_ASSIGN: begin\n                assign_idx <= assign_idx + 8'd1;\n                state <= S_CHECK_ASSIGN;\n            end\n            \n            S_DONE: begin\n                done <= 1'b1;\n                state <= S_IDLE;\n            end\n            \n            default: state <= S_IDLE;\n        endcase\n    end\nend\n\nendmodule